@app.post("/orchestrate/{pipeline_name}")
async def orchestrate(pipeline_name: str, request: Request):
    """
    Execute a pipeline and stream the response.

    Returns an SSE stream with events:
    - step: Pipeline step completion
    - chunk: LLM response chunk
    - warning: Non-fatal issues
    - error: Fatal errors
    - done: Pipeline completion
    """
    if loader is None or executor is None:
        raise HTTPException(status_code=500, detail="Server not initialized")

    # Get pipeline
    pipeline = loader.get(pipeline_name)
    if pipeline is None:
        raise HTTPException(
            status_code=404,
            detail={
                "error": {
                    "code": "pipeline_not_found",
                    "message": f"Pipeline '{pipeline_name}' not found",
                }
            },
        )

    # Parse request body
    try:
        inputs = await request.json()
    except Exception:
        inputs = {}

    # Apply defaults
    inputs = apply_defaults(pipeline, inputs)

    # Validate inputs
    errors = validate_inputs(pipeline, inputs)
    if errors:
        raise HTTPException(
            status_code=400,
            detail={
                "error": {
                    "code": "invalid_request",
                    "message": "Invalid inputs",
                    "details": {"errors": errors},
                }
            },
        )

    async def event_generator() -> AsyncGenerator[dict[str, str], None]:
        """Generate SSE events from pipeline execution."""
        async for event in executor.execute(pipeline, inputs):
            if isinstance(event, StepEvent):
                yield {
                    "event": "step",
                    "data": event.model_dump_json(exclude_none=True),
                }
            elif isinstance(event, ChunkEvent):
                yield {
                    "event": "chunk",
                    "data": event.model_dump_json(),
                }
            elif isinstance(event, WarningEvent):
                yield {
                    "event": "warning",
                    "data": event.model_dump_json(),
                }
            elif isinstance(event, ErrorEvent):
                yield {
                    "event": "error",
                    "data": event.model_dump_json(exclude_none=True),
                }
            elif isinstance(event, DoneEvent):
                yield {
                    "event": "done",
                    "data": event.model_dump_json(exclude_none=True),
                }

    return EventSourceResponse(event_generator())


def main():
    """Run the server."""
    import uvicorn

    config = get_config()
    uvicorn.run(
        "orchestrator.src.main:app",
        host="0.0.0.0",
        port=config.port,
        reload=False,
    )


if __name__ == "__main__":
    main()

"""
Variable substitution and DSL functions for pipeline execution.
"""

import json
import re
from typing import Any


class VariableError(Exception):
    """Error during variable resolution."""

    def __init__(self, ref: str, message: str):
        self.ref = ref
        self.message = message
        super().__init__(f"Variable '{ref}': {message}")


# Stopwords for keyword extraction
STOPWORDS = {
    "a", "an", "the", "is", "are", "was", "were", "be", "been", "being",
    "have", "has", "had", "do", "does", "did", "will", "would", "could",
    "should", "may", "might", "must", "shall", "can", "need", "dare",
    "ought", "used", "to", "of", "in", "for", "on", "with", "at", "by",
    "from", "as", "into", "through", "during", "before", "after",
    "above", "below", "between", "under", "again", "further", "then",
    "once", "here", "there", "when", "where", "why", "how", "all",
    "each", "few", "more", "most", "other", "some", "such", "no", "nor",
    "not", "only", "own", "same", "so", "than", "too", "very", "just",
    "and", "but", "if", "or", "because", "until", "while", "although",
    "what", "which", "who", "whom", "this", "that", "these", "those",
    "i", "me", "my", "myself", "we", "our", "ours", "ourselves", "you",
    "your", "yours", "yourself", "yourselves", "he", "him", "his",
    "himself", "she", "her", "hers", "herself", "it", "its", "itself",
    "they", "them", "their", "theirs", "themselves",
}

MIN_KEYWORD_LENGTH = 2

# Regex for finding variable references in strings
VARIABLE_PATTERN = re.compile(r"\{([^}]+)\}")

# Regex for function calls
FUNCTION_PATTERN = re.compile(r"^(\w+)\((.+)\)$")


def keywords(text: str) -> list[str]:
    """
    Extract keywords from text for search queries.

    1. Lowercase
    2. Split on non-alphanumeric
    3. Remove stopwords
    4. Remove short tokens (< 2 chars)
    5. Deduplicate preserving order

    Returns:
        List of keywords in occurrence order
    """
    if not text:
        return []

    # Lowercase and split on non-alphanumeric
    tokens = re.split(r"[^a-z0-9]+", text.lower())

    # Filter
    seen: set[str] = set()
    result: list[str] = []
    for token in tokens:
        if (
            token
            and len(token) >= MIN_KEYWORD_LENGTH
            and token not in STOPWORDS
            and token not in seen
        ):
            seen.add(token)
            result.append(token)

    return result


def join(array: list[Any], separator: str = ", ") -> str:
    """
    Join array elements into a string.

    Non-string elements are converted via str().
    None/null elements become empty strings.
    """
    if not array:
        return ""

    parts: list[str] = []
    for item in array:
        if item is None:
            parts.append("")
        elif isinstance(item, str):
            parts.append(item)
        else:
            parts.append(str(item))

    return separator.join(parts)


def resolve_variable(ref: str, context: dict[str, Any]) -> Any:
    """
    Resolve a variable reference against execution context.

    Args:
        ref: Variable reference (e.g., "session.turns", "message")
        context: Execution context dictionary

    Returns:
        Resolved value, or None if path doesn't exist
    """
    parts = ref.split(".")
    value: Any = context

    for part in parts:
        if value is None:
            return None

        # Handle array field extraction: "included[].artifact_id"
        if part.endswith("[]"):
            field = part[:-2]
            if isinstance(value, dict):
                value = value.get(field)
            else:
                return None
            # Array remains as-is for further processing
        elif isinstance(value, dict):
            value = value.get(part)
        elif isinstance(value, list) and part.isdigit():
            # Support array indexing
            idx = int(part)
            if 0 <= idx < len(value):
                value = value[idx]
            else:
                return None
        else:
            return None

    return value


def extract_array_field(array: list[dict[str, Any]], field: str) -> list[Any]:
    """
    Extract a field from each element in an array.

    Used for patterns like {docs.included[].artifact_id}
    """
    if not array:
        return []

    result: list[Any] = []
    for item in array:
        if isinstance(item, dict) and field in item:
            result.append(item[field])

    return result


def parse_function_args(args_str: str) -> list[str]:
    """
    Parse function arguments, handling quoted strings and commas.

    Examples:
        "message" -> ["message"]
        "array, ', '" -> ["array", ", "]
        'docs.ids, "; "' -> ["docs.ids", "; "]
    """
    args: list[str] = []
    current = ""
    in_quotes = False
    quote_char = None
    was_quoted = False

    i = 0
    while i < len(args_str):
        char = args_str[i]

        if not in_quotes:
            if char in ('"', "'"):
                in_quotes = True
                quote_char = char
                was_quoted = True
                # Clear any whitespace accumulated before the quote
                current = ""
            elif char == ",":
                # End of argument
                if current.strip():
                    args.append(current.strip())
                current = ""
                was_quoted = False
            else:
                current += char
        else:
            if char == quote_char:
                in_quotes = False
                quote_char = None
            else:
                current += char

        i += 1

    # Add final argument
    if was_quoted:
        args.append(current)
    elif current.strip():
        args.append(current.strip())

    return args


def call_function(name: str, args_str: str, context: dict[str, Any]) -> Any:
    """
    Call a built-in DSL function.

    Args:
        name: Function name
        args_str: Raw argument string (may contain multiple args)
        context: Execution context for resolving variable args

    Returns:
        Function result

    Raises:
        VariableError: If function is unknown
    """
    args = parse_function_args(args_str)

    if name == "keywords":
        # keywords(text) - single argument
        if not args:
            return []
        arg = args[0]
        resolved = resolve_variable(arg, context) if not arg.startswith(('"', "'")) else arg
        if not isinstance(resolved, str):
            resolved = str(resolved) if resolved else ""
        return keywords(resolved)

    elif name == "join":
        # join(array, separator) - two arguments, separator optional
        if not args:
            return ""

        # First arg is the array reference
        array_ref = args[0]
        resolved_array = resolve_variable(array_ref, context)

        # Second arg (optional) is the separator
        separator = ", "
        if len(args) > 1:
            sep_arg = args[1]
            # Remove quotes if present
            if sep_arg.startswith(('"', "'")) and sep_arg.endswith(sep_arg[0]):
                separator = sep_arg[1:-1]
            else:
                separator = sep_arg

        if isinstance(resolved_array, list):
            return join(resolved_array, separator)
        return str(resolved_array) if resolved_array else ""

    else:
        raise VariableError(f"{name}({args_str})", f"Unknown function '{name}'")


def resolve_reference(ref: str, context: dict[str, Any]) -> Any:
    """
    Resolve a reference which may be a variable or function call.

    Args:
        ref: Reference string (e.g., "message", "session.turns", "keywords(message)")
        context: Execution context

    Returns:
        Resolved value
    """
    ref = ref.strip()

    # Check for function call
    func_match = FUNCTION_PATTERN.match(ref)
    if func_match:
        func_name = func_match.group(1)
        func_arg = func_match.group(2).strip()
        return call_function(func_name, func_arg, context)

    # Check for array field extraction: something[].field
    if "[]." in ref:
        parts = ref.split("[].")
        if len(parts) == 2:
            array_ref = parts[0]
            field = parts[1]
            array = resolve_variable(array_ref, context)
            if isinstance(array, list):
                return extract_array_field(array, field)
            return None

    # Simple variable reference
    return resolve_variable(ref, context)


def serialize_turns(turns: list[dict[str, Any]]) -> str:
    """
    Serialize turns array for prompt context.

    Format:
    User: {user message}
    Assistant: {assistant message}

    User: {user message}
    Assistant: {assistant message}
    """
    if not turns:
        return ""

    parts: list[str] = []
    for turn in turns:
        user = turn.get("user", "")
        assistant = turn.get("assistant", "")
        parts.append(f"User: {user}\nAssistant: {assistant}")

    return "\n\n".join(parts)


def serialize_for_prompt(value: Any) -> str:
    """
    Serialize value for prompt string interpolation.
    """
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        # Check if it's a turns array (has user/assistant)
        if value and isinstance(value[0], dict) and "user" in value[0]:
            return serialize_turns(value)
        # Default: JSON array
        return json.dumps(value, indent=2)
    if isinstance(value, dict):
        return json.dumps(value, indent=2)
    return str(value)


def interpolate(template: str, context: dict[str, Any]) -> str:
    """
    Interpolate variables in a template string.

    If the template is exactly one variable reference, preserve the resolved type.
    Otherwise, convert all references to strings.

    Args:
        template: Template string with {variable} references
        context: Execution context

    Returns:
        Interpolated string
    """
    if not template:
        return ""

    # Check if entire string is a single variable reference
    stripped = template.strip()
    if (
        stripped.startswith("{")
        and stripped.endswith("}")
        and stripped.count("{") == 1
    ):
        ref = stripped[1:-1]
        value = resolve_reference(ref, context)
        # For prompt contexts, serialize complex types
        return serialize_for_prompt(value)

    # Multiple references or mixed content - interpolate all
    def replace_match(match: re.Match[str]) -> str:
        ref = match.group(1)
        value = resolve_reference(ref, context)
        return serialize_for_prompt(value)

    return VARIABLE_PATTERN.sub(replace_match, template)


def interpolate_value(value: Any, context: dict[str, Any]) -> Any:
    """
    Recursively interpolate variables in a value.

    Handles strings, lists, and dicts. Preserves types when possible.

    Args:
        value: Value to interpolate (may contain {variable} references)
        context: Execution context

    Returns:
        Interpolated value with same structure
    """
    if isinstance(value, str):
        # Check if entire string is a single variable reference
        stripped = value.strip()
        if (
            stripped.startswith("{")
            and stripped.endswith("}")
            and stripped.count("{") == 1
        ):
            ref = stripped[1:-1]
            return resolve_reference(ref, context)

        # Otherwise interpolate as string
        def replace_match(match: re.Match[str]) -> str:
            ref = match.group(1)
            resolved = resolve_reference(ref, context)
            return serialize_for_prompt(resolved)

        return VARIABLE_PATTERN.sub(replace_match, value)

    elif isinstance(value, dict):
        return {k: interpolate_value(v, context) for k, v in value.items()}

    elif isinstance(value, list):
        return [interpolate_value(item, context) for item in value]

    else:
        return value
